css:
.dcx,.dcx{margin:0;padding:0;background:#FFFFFF;font-family:'Plus Jakarta Sans',system-ui,sans-serif;color:#0B2018;-webkit-font-smoothing:antialiased}
.dcx a{color:#0B3B29;text-decoration:none}
.dcx a:hover{color:#0E8A52}
.dcx *:focus-visible{outline:2px solid #0E8A52;outline-offset:2px}
.dcx .nx-btn{transition:transform .16s ease-out,box-shadow .16s ease-out,background .16s,color .16s}
.dcx .nx-btn:hover{transform:translateY(-1px);box-shadow:0 10px 22px -12px rgba(7,120,76,.5)}
.dcx .nx-arr{display:inline-flex;transition:transform .16s ease-out}
.dcx .nx-btn:hover .nx-arr{transform:translateX(3px)}
.dcx .nx-card{transition:transform .18s ease-out,box-shadow .18s ease-out,border-color .18s}
.dcx .nx-card:hover{transform:translateY(-2px);box-shadow:0 16px 32px -22px rgba(11,32,24,.4);border-color:#CFE3D8}
.dcx .nx-row{transition:background .15s}
.dcx .nx-row:hover{background:#F7FAF8}
@keyframes nxUp{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}
.dcx [data-anim]{animation:nxUp .62s cubic-bezier(.22,.8,.3,1) both}
@keyframes nxFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-7px)}}
.dcx .nx-float{animation:nxFloat 5.5s ease-in-out infinite}
@keyframes nxPulse{0%,100%{opacity:.45;transform:scale(1)}50%{opacity:1;transform:scale(1.3)}}
.dcx .nx-pulse{animation:nxPulse 2.4s ease-in-out infinite}
@keyframes nxDash{to{stroke-dashoffset:-66}}
.dcx .nx-dash{stroke-dasharray:5 6;animation:nxDash 2.6s linear infinite}
@media (max-width:1150px){.dcx [data-nx-nav]{display:none!important}
}
@media (max-width:1040px){.dcx [data-nx="split"]{grid-template-columns:minmax(0,1fr)!important;gap:30px!important}
.dcx [data-nx="app"]{grid-template-columns:minmax(0,1fr)!important}
.dcx [data-nx="app"] [data-nx="side"]{display:none!important}
.dcx [data-nx="g6"]{grid-template-columns:repeat(3,minmax(0,1fr))!important;row-gap:26px!important}
.dcx [data-nx="g3"]{grid-template-columns:repeat(2,minmax(0,1fr))!important}
.dcx [data-nx="howrow"]{grid-template-columns:minmax(0,1fr)!important}
.dcx [data-nx="techrow"]{grid-template-columns:minmax(0,1fr)!important}
.dcx [data-nx="phone"]{display:none!important}
.dcx [data-nx="tablecols"],.dcx [data-nx="filters"]{display:none!important}
.dcx [data-nx="calbody"]{grid-template-columns:118px minmax(0,1fr)!important}
}
@media (max-width:760px){.dcx [data-nx="g6"]{grid-template-columns:repeat(2,minmax(0,1fr))!important}
.dcx [data-nx="g3"]{grid-template-columns:repeat(1,minmax(0,1fr))!important}
.dcx [data-nx="ctabar"]{grid-template-columns:minmax(0,1fr)!important}
.dcx [data-nx="hide"]{display:none!important}
.dcx section > div{padding-left:18px!important;padding-right:18px!important}
}

